			if memberMatches(r, members) == negate {
				return false
			}
			key = key[n:]
			pat = pat[2+closeIdx:]
		default:
			if key == "" {
				return false
			}
			pr, pn, ok1 := utf8.DecodeRuneInString(pat)
			kr, kn, ok2 := utf8.DecodeRuneInString(key)
			if !ok1 || !ok2 || kr != pr {
				return false
			}
			key, pat = key[kn:], pat[pn:]
		}
	}
}

func stringsTrimLeft(s string, c byte) string {
	for len(s) > 0 && s[0] == c {
		s = s[1:]
	}
	return s
}

// memberMatches reports whether r is in the bracket member expression
// (ranges like a-z and single characters).
func memberMatches(r rune, members string) bool {
	i := 0
	for i < len(members) {
		m, n, ok := utf8.DecodeRuneInString(members[i:])
		if !ok {
			i++
			continue
		}
		if m == '-' && i > 0 && i+n < len(members) {
			lo, _, ok1 := utf8.DecodeRuneInString(members[i-1:])
			hi, _, ok2 := utf8.DecodeRuneInString(members[i+n:])
			if ok1 && ok2 && r >= lo && r <= hi {
				return true
			}
			i += 2 * n // skip the range upper bound
		} else if r == m {
			return true
		}
		i += n
	}
	return false
}","path":"store/store.go"}

