{"content":"package store

import (
	"bytes"
	"errors"
	"strings"
	"testing"
	"time"
)

type fakeClock struct{ now time.Time }

func (c *fakeClock) tick() time.Time { return c.now }
func (c *fakeClock) advance(d time.Duration) { c.now = c.now.Add(d) }

func newTestStore(t *testing.T) (*Store, *fakeClock) {
	t.Helper()
	cl := &fakeClock{now: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
	return New(cl.tick), cl
}

func TestSetGet(t *testing.T) {
	s, _ := newTestStore(t)
	if v, ok := s.Get("k"); ok || v != "" {
		t.Fatalf("missing key: got %q, %v", v, ok)
	}
	s.Set("k", "v", 0)
	if v, ok := s.Get("k"); !ok || v != "v" {
		t.Fatalf("Get = %q, %v", v, ok)
	}
	// Set replaces both value and ttl.
	s.Set("k", "v2", time.Minute)
	if v, ok := s.Get("k"); !ok || v != "v2" {
		t.Fatalf("after replace: %q, %v", v, ok)
	}
	s.Set("k", "v3", 0)
	if got := s.TTL("k"); got != -1 {
		t.Fatalf("TTL after re-set without ttl = %v, want -1", got)
	}
}

func TestExpiry(t *testing.T) {
	s, cl := newTestStore(t)
	s.Set("k", "v", time.Second)
	if !s.Exists("k") {
		t.Fatal("exists before expiry")
	}
	cl.advance(500 * time.Millisecond)
	if !s.Exists("k") {
		t.Fatal("exists before deadline")
	}
	cl.advance(501 * time.Millisecond) // now >= deadline
	if s.Exists("k") {
		t.Fatal("expired key should behave as missing")
	}
	if _, ok := s.Get("k"); ok {
		t.Fatal("Get on expired key")
	}
	if s.Len() != 0 {
		t.Fatalf("Len counts expired key: %d", s.Len())
	}
	if keys := s.Keys("*"); len(keys) != 0 {
		t.Fatalf("Keys includes expired: %v", keys)
	}
}

func TestDel(t *testing.T) {
	s, _ := newTestStore(t)
	s.Set("a", "1", 0)
	s.Set("b", "2", 0)
	s.Set("c", "3", time.Second)
	if n := s.Del("a", "b", "z"); n != 2 {
		t.Fatalf("Del = %d, want 2", n)
	}
	if n := s.Del("a"); n != 0 {
		t.Fatalf("Del again = %d, want 0", n)
	}
}

func TestExpirePersist(t *testing.T) {
	s, cl := newTestStore(t)
	if s.Expire("missing", time.Second) {
		t.Fatal("Expire on missing key")
	}
	s.Set("k", "v", 0)
	if s.Persist("k") {
		t.Fatal("Persist without expiry should be false")
	}
	if !s.Expire("k", time.Minute) {
		t.Fatal("Expire existing")
	}
	if got := s.TTL("k"); got <= 0 || got > time.Minute {
		t.Fatalf("TTL = %v", got)
	}
	if !s.Persist("k") {
		t.Fatal("Persist with expiry should be true")
	}
	if got := s.TTL("k"); got != -1 {
		t.Fatalf("TTL after persist = %v", got)
	}
	// ttl <= 0 deletes the key.
	s.Expire("k", time.Minute)
	if !s.Expire("k", 0) {
		t.Fatal("Expire ttl=0 should delete and return true")
	}
	if s.Exists("k") {
		t.Fatal("key should be deleted")
	}
	// Expired key: Expire reports missing.
	s.Set("e", "v", time.Second)
	cl.advance(2 * time.Second)
	if s.Expire("e", time.Minute) {
		t.Fatal("Expire on expired key should be false")
	}
}

func TestTTL(t *testing.T) {
	s, cl := newTestStore(t)
	if got := s.TTL("nope"); got != -2 {
		t.Fatalf("TTL missing = %v, want -2", got)
	}
	s.Set("a", "1", 0)
	if got := s.TTL("a"); got != -1 {
		t.Fatalf("TTL no expiry = %v, want -1", got)
	}
	s.Set("b", "1", time.Second)
	cl.advance(200 * time.Millisecond)
	if got := s.TTL("b"); got != 800*time.Millisecond {
		t.Fatalf("TTL = %v, want 800ms", got)
	}
}

func TestIncr(t *testing.T) {
	s, _ := newTestStore(t)
	if v, err := s.Incr("n", 5); err != nil || v != 5 {
		t.Fatalf("Incr new = %d, %v", v, err)
	}
	if v, err := s.Incr("n", -2); err != nil || v != 3 {
		t.Fatalf("Incr = %d, %v", v, err)
	}
	if v, err := s.Incr("n", 7); err != nil || v != 10 {
		t.Fatalf("Incr = %d, %v", v, err)
	}
	s.Set("x", "abc", 0)
	if _, err := s.Incr("x", 1); !errors.Is(err, ErrNotInteger) {
		t.Fatalf("Incr non-integer err = %v", err)
	}
	// Existing ttl is kept.
	s, cl := newTestStore(t)
	s.Set("t", "1", time.Second)
	cl.advance(500 * time.Millisecond)
	s.Incr("t", 1)
	if got := s.TTL("t"); got != 500*time.Millisecond {
		t.Fatalf("TTL after incr = %v, want 500ms", got)
	}
}

func TestKeysGlob(t *testing.T) {
	s, _ := newTestStore(t)
	for _, k := range []string{"user1", "user2", "admin", "user/foo", "a/b/c"} {
		s.Set(k, "v", 0)
	}
	check := func(pattern string, want ...string) {
		t.Helper()
		got := s.Keys(pattern)
		if len(got) != len(want) {
			t.Fatalf("Keys(%q) = %v, want %v", pattern, got, want)
		}
		for i := range want {
			if got[i] != want[i] {
				t.Fatalf("Keys(%q) = %v, want %v", pattern, got, want)
			}
		}
	}
	check("*", "a/b/c", "admin", "user/foo", "user1", "user2")
	check("user*", "user/foo", "user1", "user2") // * matches '/'
	check("user?", "user1", "user2")
	check("u*1", "user1")
	check("a[bc]min", "admin")
	check("u[0-2]ser2", "user2")
	check("u[^/]ser1", "user1")
	check("u[!/]ser1", "user1")
	check("a/b/c", "a/b/c")
	check("a\\/b\\/c", "a/b/c")
	check("user\\/", "user/foo")
	check("a?/c", "a/b/c")
	check("nope*", )
	check("", )
}

func TestLen(t *testing.T) {
	s, cl := newTestStore(t)
	s.Set("a", "1", 0)
	s.Set("b", "2", time.Second)
	if n := s.Len(); n != 2 {
		t.Fatalf("Len = %d", n)
	}
	cl.advance(2 * time.Second)
	if n := s.Len(); n != 1 {
		t.Fatalf("Len after expiry = %d", n)
	}
}

func TestSaveLoad(t *testing.T) {
	s, _ := newTestStore(t)
	s.Set("b", "2", 30*time.Second)
	s.Set("a", "1", 0)
	s.Set("gone", "x", time.Second) // expires at 1s; clock is at 0
	var buf bytes.Buffer
	if err := s.Save(&buf); err != nil {
		t.Fatal(err)
	}
	exp := `{"version":1,"entries":[{"k":"a","v":"1","exp":0},{"k":"b","v":"2","exp":30000}]}`
	if buf.String() != exp {
		t.Fatalf("Save output:\n%s\nwant:\n%s", buf.String(), exp)
	}
	// Round-trip into a fresh store.
	s2, _ := newTestStore(t)
	if err := s2.Load(&buf); err != nil {
		t.Fatal(err)
	}
	if v, ok := s2.Get("a"); !ok || v != "1" {
		t.Fatalf("loaded a = %q, %v", v, ok)
	}
	if v, ok := s2.Get("b"); !ok || v != "2" {
		t.Fatalf("loaded b = %q, %v", v, ok)
	}
	if got := s2.TTL("b"); got <= 0 || got > 30*time.Second {
		t.Fatalf("TTL(b) = %v", got)
	}
	if s2.Exists("gone") {
		t.Fatal("expired entry should be dropped")
	}
	if n := s2.Len(); n != 2 {
		t.Fatalf("Len = %d", n)
	}
	// Load replaces all contents.
	s.Set("z", "9", 0)
	if err := s.Load(&buf); err != nil {
		t.Fatal(err)
	}
	if s.Exists("z") || s.Len() != 2 {
		t.Fatalf("Load should replace contents; Len=%d", s.Len())
	}
	// Wrong version rejected.
	if err := s.Load(strings.NewReader(`{"version":2,"entries":[]}`)); err == nil {
		t.Fatal("expected error for version 2")
	}
	// Expired at load time (clock has moved past the 30s deadline? no) —
	// simulate by building a snapshot whose exp is in the past.
	other, cl := newTestStore(t)
	cl.advance(60 * time.Second)
	if err := other.Load(&buf); err != nil {
		t.Fatal(err)
	}
	if other.Exists("b") {
		t.Fatal("entry expired at load time should be dropped")
	}
}

func TestConcurrent(t *testing.T) {
	s, _ := newTestStore(t)
	done := make(chan struct{})
	for i := 0; i < 8; i++ {
		go func(i int) {
			defer func() { done <- struct{}{} }()
			key := "k"
			if i%2 == 1 {
				key = "n"
			}
			for j := 0; j < 100; j++ {
				s.Set(key, "v", time.Second)
				s.Get(key)
				s.Exists(key)
				s.Del(key)
				s.Incr("n", 1)
				s.Keys("*")
				s.Len()
				s.TTL(key)
			}
		}(i)
	}
	for i := 0; i < 8; i++ {
		<-done
	}
}
