{"content":"package server

import (
	"bufio"
	"context"
	"fmt"
	"net"
	"strings"
	"testing"
	"time"

	"example.com/kv/store"
)

// start begins a server on a fresh port. It returns the address, a cancel
// function and a channel that receives Serve's return value.
func start(t *testing.T) (string, context.CancelFunc, <-chan error) {
	t.Helper()
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithCancel(context.Background())
	t.Cleanup(cancel)
	errc := make(chan error, 1)
	go func() { errc <- Serve(ctx, l, store.New(nil)) }()
	return l.Addr().String(), cancel, errc
}

func dial(t *testing.T, addr string) net.Conn {
	t.Helper()
	c, err := net.Dial("tcp", addr)
	if err != nil {
		t.Fatal(err)
	}
	c.SetDeadline(time.Now().Add(10 * time.Second))
	return c
}

// expectLine writes req (which must end with '\n') and checks the
// full multi-line response.
func expectLine(t *testing.T, c net.Conn, req, want string) {
	t.Helper()
	if _, err := c.Write([]byte(req)); err != nil {
		t.Fatalf("write %q: %v", req, err)
	}
	got, err := readResponse(t, c)
	if err != nil {
		t.Fatalf("read response to %q: %v", req, err)
	}
	if got != want {
		t.Fatalf("response to %q = %q, want %q", req, got, want)
	}
}

// readResponse reads a full response (an array spans multiple lines).
func readResponse(t *testing.T, c net.Conn) (string, error) {
	t.Helper()
	br := bufio.NewReader(c)
	first, err := br.ReadString('\n')
	if err != nil {
		return "", err
	}
	out := first
	if strings.HasPrefix(first, "*") {
		var n int
		if _, err := fmt.Sscanf(first, "*%d", &n); err != nil {
			return "", err
		}
		for i := 0; i < n; i++ {
			line, err := br.ReadString('\n')
			if err != nil {
				return "", err
			}
			out += line
		}
	}
	return out, nil
}

func TestServeRoundTrip(t *testing.T) {
	addr, _, _ := start(t)
	c := dial(t, addr)
	expectLine(t, c, "PING\n", "+PONG\n")
	expectLine(t, c, "PING\r\n", "+PONG\n")
	expectLine(t, c, "SET hello \"world wide web\"\n", "+OK\n")
	expectLine(t, c, "GET hello\n", `$"world wide web"\n`)
	expectLine(t, c, "DBSIZE\n", ":1\n")
	expectLine(t, c, "KEYS *\n", "*1\n$hello\n")
	expectLine(t, c, "QUIT\n", "+BYE\n")
	// The server must have closed the connection.
	c.SetReadDeadline(time.Now().Add(5 * time.Second))
	if _, err := c.Read(make([]byte, 1)); err == nil {
		t.Fatal("expected EOF after QUIT, got data")
	}
}

func TestServeMultipleClients(t *testing.T) {
	addr, _, _ := start(t)
	c1 := dial(t, addr)
	c2 := dial(t, addr)
	expectLine(t, c1, "SET a 1\n", "+OK\n")
	expectLine(t, c2, "GET a\n", "$1\n")
	expectLine(t, c1, "QUIT\n", "+BYE\n")
	// The other client keeps working.
	expectLine(t, c2, "PING\n", "+PONG\n")
	expectLine(t, c2, "QUIT\n", "+BYE\n")
}

func TestServeLongLine(t *testing.T) {
	addr, _, _ := start(t)
	c := dial(t, addr)
	long := strings.Repeat("a", 70*1024) + "\n"
	if _, err := c.Write([]byte(long)); err != nil {
		t.Fatal(err)
	}
	got, err := readResponse(t, c)
	if err != nil {
		t.Fatal(err)
	}
	if got != "-ERR line too long\n" {
		t.Fatalf("response = %q", got)
	}
	// Connection is closed afterwards.
	c.SetReadDeadline(time.Now().Add(5 * time.Second))
	if _, err := c.Read(make([]byte, 1)); err == nil {
		t.Fatal("expected EOF after too-long line, got data")
	}
	// A line of exactly 64 KiB is fine.
	c2 := dial(t, addr)
	ok := strings.Repeat("a", 64*1024) + "\n"
	expectLine(t, c2, ok, "+PONG\n")
}

func TestServeCancel(t *testing.T) {
	addr, cancel, errc := start(t)
	c := dial(t, addr)
	expectLine(t, c, "PING\n", "+PONG\n")
	cancel()
	select {
	case err := <-errc:
		if err != nil {
			t.Fatalf("Serve returned %v, want nil", err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("Serve did not return after cancel")
	}
}
","path":"server/server_test.go"}

msg.reasoning_content:
in the problem: TestServeLongLine's final part: `expectLine(t, c2, ok, "+PONG\n")` — I'm sending 64KiB of 'a's + \n as a "request". That's an invalid line ("aaaa..." 64k a's) — the first token is "aaa...a" (64k a's) → unknown command, and the response becomes `-ERR unknown command 'aaa...'\n` — not +PONG. My mistake. The intent was: a long-but-not-too-long line should be processed normally. I should send "PING" padded to exactly 64KiB… but in that case the padding becomes part of the first token "PING<aaaa...>" → unknown command. Better approach: pad with trailing spaces: "PING" + 64KiB-4 spaces + "\n" → the line length is exactly 64KiB, tokens: PING (trailing spaces are delimiters) → +PONG.

Let me fix it: `ok := "PING" + strings.Repeat(" ", 64*1024-4) + "\n"`.

Also, the first part of the test: after the server closes the connection c, dialing c2 is a new connection — no problem.

Another concern: `if _, err := c.Read(make([]byte, 1)); err == nil` — if the server closes cleanly, the first Read might return 0 bytes with a nil error! TCP FIN → Read returns 0, nil. Hmm: a Read that returns 0 bytes along with a nil error is legal but rare in practice; does it happen with net.Conn? "In certain cases, a call to Read may return 0, nil" — for TCP connections with a pending FIN, Read normally returns 0, io.EOF. There are edge cases where it returns 0, nil. To be safe, use a loop: read until an error or data; fail if data is received. Let me write a helper `expectClosed(t, c)`:

```go
buf := make([]byte, 1)
for {
    n, err := c.Read(buf)
    if err != nil { return }
    if n > 0 { t.Fatal("unexpected data after close") }
}
```

